"""make_spec_v2.py -- report v2 = part 1 (spec_v1.json) + part 2 profile sections from results_v2.json. Numbers come only from the two results files."""
import json, sys
from pathlib import Path
OUT = Path(sys.argv[1])
spec = json.load(open(OUT / "spec_v1.json")); R2 = json.load(open(OUT / "results_v2.json"))
pct = lambda x, d=0: f"{100 * x:.{d}f}%"
ft = lambda i: f"{int(i) // 12}'{int(i) % 12}\""
Q1, Q1f, Q2, Q3, Q4, PR, FN = R2["Q1_mlb7"], R2["Q1_fv50"], R2["Q2"], R2["Q3"], R2["Q4"], R2["profile"], R2["funnel"]
SH, HB, SP, SO, PC, LB = R2["Q1_share"], R2["height_bands"], R2["size_profile"], R2["side_output"], R2["position_changes"], R2["late_bloomers"]
full = FN[3]; big = PR["n_big"]
spec["page_title"] = "International Money and Talent"
spec["h1"] = "International money and talent, 2016–26 signing classes"
spec["dek"] = ("Where clubs spent in the international amateur market, what came out of it, and what a future big leaguer looked like at signing and in his first three years. "
               "Money buys prospect status more than big leaguers, position and size add little once you know the bonus, and by year three you can usually tell.")
spec["byline"] = spec["byline"].replace("Published Nov 5, 2026", "Published Nov 5, 2026 · v2 adds player types, sizes and early paths")
spec["tiles"][3] = {"v": pct(full["share_of_big_leaguers"]), "l": "of big leaguers were in full-season ball by their third pro season"}
spec["findings"].insert(3, {"b": "Player type and size add little once you know the bonus.", "t": f"Shortstops are {pct(SH['SS']['share_signees'])} of signees but {pct(SH['SS']['share_mlb'])} of big leaguers, and left-handers and catchers are under-represented. Bonus tier explains most of that (position test p = {Q1['p']:.2f}). At signing, big leaguers measured the same as everyone else: pitchers a median {ft(SP['pitchers']['mlb_h'])}, {SP['pitchers']['mlb_w']:.0f} lb; hitters {ft(SP['hitters']['mlb_h'])}, {SP['hitters']['mlb_w']:.0f} lb. All four size tests failed."})
spec["findings"].insert(4, {"b": "By year three you can usually tell.", "t": f"{pct(full['share_of_big_leaguers'])} of future big leaguers were in full-season ball by their third pro season. Of the cheap signees who weren't, {pct(R2['path_by_tier']['C']['not']['rate'], 1)} made it. That early path sorts big leaguers far better than the bonus did (AUC {Q3['auc_fullseason_s3']:.2f} vs {Q3['auc_tier']:.2f})."})

POSL = {"RHP": "Right-handed pitcher", "LHP": "Left-handed pitcher", "C": "Catcher", "SS": "Shortstop", "Other IF": "Other infield", "OF": "Outfield"}
types = {"kicker": "Player types", "h2": "Shortstops are over-represented among big leaguers, but mostly because they get the money.", "blocks": [
 {"p": f"Position at signing comes from the signing transaction and is known for {pct(R2['Q1_mlb7']['n'] / PR['n_signees'])} of signees. Shortstops reach the majors at the highest rate. Catchers and left-handers reach at about a third of that rate. The share chart sets each position's share of all 2016–19 signees against its share of the {big} big leaguers."},
 {"chart": {"type": "dumbbell", "title": "Share of signees vs share of big leaguers, by position at signing", "sub": "2016–19 classes", "fmt": "pct0",
   "series": [{"key": "a", "label": "Share of signees", "color": "s2"}, {"key": "b", "label": "Share of big leaguers", "color": "s1"}],
   "rows": [{"label": POSL[g], "a": SH[g]["share_signees"], "b": SH[g]["share_mlb"], "note": f"{Q1['by_group'][g]['hits']} of {Q1['by_group'][g]['n']:,} reached MLB",
             "tip": [f"Rate {pct(Q1['by_group'][g]['rate'], 1)} (95% CI {pct(Q1['by_group'][g]['ci'][0], 1)}–{pct(Q1['by_group'][g]['ci'][1], 1)})", f"WAR in first seven seasons: {SH[g]['war7']:.1f}",
                     f"FV 50+ (2016–22): {pct(Q1f['by_group'][g]['rate'], 1)}"]} for g in ["RHP", "LHP", "C", "SS", "Other IF", "OF"]]}},
 {"p": f"Test Q1 asked whether position still matters once bonus tier and class are known. It **fails** for reaching MLB (p = {Q1['p']:.2f}) and for becoming a 50+ FV prospect (p = {Q1f['p']:.2f}). Shortstops look good mostly because clubs pay them. One contrast is worth watching but is not proven: once the bonus is known, catchers were about {Q1f['odds_vs_RHP_after_tier']['C'][0]:.1f} times as likely as right-handed pitchers to become 50+ FV prospects, yet they reached MLB at only {pct(Q1['by_group']['C']['rate'], 1)}. Prospect grades may like young catchers more than the position ends up rewarding."},
 {"h3": "Hitters make up about half the big leaguers and most of the value"},
 {"p": f"Hitters were {pct(SO['Hitters']['signees'] / (SO['Hitters']['signees'] + SO['Pitchers']['signees']))} of 2016–19 signees and reached MLB at {pct(SO['Hitters']['rate'], 1)}, against {pct(SO['Pitchers']['rate'], 1)} for pitchers. They produced {pct(SO['Hitters']['war7'] / (SO['Hitters']['war7'] + SO['Pitchers']['war7']))} of the first-seven-season WAR ({SO['Hitters']['war7']:.0f} vs {SO['Pitchers']['war7']:.0f}). Left-handers were {pct(PR['lhp_share_of_pitchers_signees'])} of the pitchers signed but {pct(PR['lhp_share_of_pitchers_big'])} of the pitchers who made it."},
 {"p": f"Position at signing is a starting point, not a destination. Of the {PC['signed_ss']} big leaguers from the 2016–22 classes who signed as shortstops, {PC['signed_ss_mlb_pos'].get('SS', 0)} played mostly shortstop in the majors. {PC['signed_ss_mlb_pos'].get('2B', 0)} moved to second and {PC['signed_ss_mlb_pos'].get('3B', 0)} to third. Catchers stayed put: {PC['signed_c_mlb_pos'].get('C', 0)} of {PC['signed_c']}. Hitter-to-pitcher conversions were rare; the clearest one is Daysbel Hernández, who signed as an outfielder and pitched in the majors."},
 {"table": {"head": ["Signed as", "Best producer", "Class", "Bonus", "WAR"], "num": [2, 3, 4], "names": [1],
   "rows": [[POSL[g], r[0], str(r[1]), (f"${r[2] / 1e6:.2f}M" if r[2] and r[2] >= 1e6 else (f"${r[2] / 1e3:.0f}K" if r[2] else "Not recorded")), f"{r[5]:.1f}"]
            for g in ["C", "SS", "Other IF", "OF", "RHP", "LHP"] for r in [next(x for x in R2["best_by_pos"][g] if x[0] != "Alejandro Kirk")]],
   "caption": "Most WAR through 2026 by position at signing, 2016–22 classes. Alejandro Kirk is left out: the transaction log lists him as a right-handed pitcher at signing, but he signed as a catcher."}}]}

size = {"kicker": "Size and age", "h2": "At signing, future big leaguers were built like everyone else.", "blocks": [
 {"p": f"Height and weight near signing exist only for players on a public list within two seasons of signing. That is {pct(PR['early_listed_share_signees'], 1)} of 2016–19 signees, but {pct(PR['early_listed_share_big'])} of the eventual big leaguers. Within that group, big leaguers matched everyone else. Pitchers who made it had a median of {ft(SP['pitchers']['mlb_h'])}, {SP['pitchers']['mlb_w']:.0f} lb (middle half {ft(SP['pitchers']['mlb_h_iqr'][0])}–{ft(SP['pitchers']['mlb_h_iqr'][1])}), the same as all listed pitchers. Hitters who made it had a median of {ft(SP['hitters']['mlb_h'])}, {SP['hitters']['mlb_w']:.0f} lb, against {ft(SP['hitters']['all_h'])}, {SP['hitters']['all_w']:.0f} lb for all listed hitters."},
 {"p": f"Test Q2 asked whether height and weight help once the bonus is known, separately for pitchers and hitters and for both outcomes. All four **fail**, and none comes close. One pattern is worth noting (exploratory, small samples): tall hitters got the prospect grades but not the big-league careers. Hitters 6'3\" or taller became 50+ FV prospects at {pct(HB['hitters_fv50']['6\'3\"+']['rate'])}, against {pct(HB['hitters_fv50']['5\'10\" or less']['rate'])} for those 5'10\" or shorter. They reached MLB at {pct(HB['hitters_mlb7']['6\'3\"+']['rate'])}, against {pct(HB['hitters_mlb7']['5\'10\" or less']['rate'])}."},
 {"chart": {"type": "bars", "title": "Listed hitters by height near signing: prospect grade vs reaching MLB", "sub": "Listed hitters only. FV 50+: 2016–22 classes. MLB: 2016–19 classes", "fmt": "pct0",
   "series": [{"key": "a", "label": "Reached MLB within 7 seasons", "color": "s1"}, {"key": "b", "label": "Became a 50+ FV prospect", "color": "s2"}],
   "rows": [{"label": b, "values": {"a": HB["hitters_mlb7"][b]["rate"], "b": HB["hitters_fv50"][b]["rate"]},
             "tip": [f"MLB: {HB['hitters_mlb7'][b]['hits']} of {HB['hitters_mlb7'][b]['n']}", f"FV 50+: {HB['hitters_fv50'][b]['hits']} of {HB['hitters_fv50'][b]['n']}"]} for b in HB["hitters_mlb7"]]}},
 {"p": f"Age at signing doesn't separate them either. Test Q4 compared signing at 17 or older with signing at 16, after bonus tier, among listed signees. The odds ratio was {Q4['or_older']:.2f} (CI {Q4['ci'][0]:.2f}–{Q4['ci'][1]:.2f}), so the test **fails**. The big leaguers debuted at a median age of {PR['debut_age_median']:.1f}, and most debuted between 21 and 24."},
 {"note": "A first run of the age test used every known birth date. Birth dates exist for every big leaguer but only 12% of everyone else, so that cohort was selected on the outcome. It was discarded and rerun on listed players (see PREREG_v2_AMENDMENTS.md). Its result was also null."}]}

path = {"kicker": "The first three years", "h2": "Year three is where the picture comes into focus.", "blocks": [
 {"p": f"Each signee's first seasons are traced through his assignments (2020 skipped). This is where future big leaguers separate from the field. Nearly every one of them was still with a club after two seasons, out of the DSL by his second season, and in full-season ball by his third. Each step cuts the field sharply but keeps almost all of the big leaguers."},
 {"chart": {"type": "bars", "title": "Each stage's share of all signees and of the eventual big leaguers", "sub": "2016–19 classes", "fmt": "pct0",
   "series": [{"key": "a", "label": "Share of eventual big leaguers", "color": "s1"}, {"key": "b", "label": "Share of all signees", "color": "s2"}],
   "rows": [{"label": f["stage"], "values": {"a": f["share_of_big_leaguers"], "b": f["share_of_signees"]}, "tip": [f"{f['n']:,} signees, {f['mlb7']} big leaguers", f"MLB rate at this stage: {pct(f['mlb_rate'], 1)}"]} for f in FN[:4]]}},
 {"p": f"Test Q3 asked whether 'in full-season ball by year three' sorts future big leaguers better than the bonus did at signing. It does: AUC {Q3['auc_fullseason_s3']:.2f} against {Q3['auc_tier']:.2f}, a gap of {Q3['diff']:.2f} (CI {Q3['ci'][0]:.2f}–{Q3['ci'][1]:.2f}). The test **passes** and survives correction. The miss rate for cheap signees is the useful number: of the {R2['path_by_tier']['C']['not']['n']:,} under-$300K signees who weren't in full-season ball by year three, {R2['path_by_tier']['C']['not']['hits']} reached MLB ({pct(R2['path_by_tier']['C']['not']['rate'], 1)}). For those who were, the rate was {pct(R2['path_by_tier']['C']['full_s3']['rate'], 1)}."},
 {"chart": {"type": "bars", "title": "Reached MLB within seven seasons, by bonus tier and year-three level", "sub": "2016–19 classes", "fmt": "pct0",
   "series": [{"key": "a", "label": "In full-season ball by year three", "color": "s1"}, {"key": "b", "label": "Not yet", "color": "s2"}],
   "rows": [{"label": lab, "values": {"a": R2["path_by_tier"][t]["full_s3"]["rate"], "b": R2["path_by_tier"][t]["not"]["rate"]},
             "tip": [f"Full-season by year three: {R2['path_by_tier'][t]['full_s3']['hits']} of {R2['path_by_tier'][t]['full_s3']['n']:,}", f"Not yet: {R2['path_by_tier'][t]['not']['hits']} of {R2['path_by_tier'][t]['not']['n']:,}"]}
            for t, lab in (("A", "$1M or more"), ("B", "$300K–$999K"), ("C", "Under $300K or none reported"))]}},
 {"p": f"The exceptions are real, but few. {LB['not_full_by_s3']} of the {LB['big_leaguers']} big leaguers were not in full-season ball by year three: Maikel Garcia and Yainer Díaz are the best of them. {LB['released_then_mlb']} were released before they debuted. {PR['traded_before_debut']} of the {big} ({pct(PR['traded_before_debut'] / big)}) were traded before their debut, so a third of these big leaguers debuted for a club that did not sign them."},
 {"callout": "What this means for coverage: the signing-day decision is a low-information bet, about 3% in aggregate. Within three years the picture sharpens a lot, which makes the second and third pro seasons a natural point to re-evaluate, trade for, or protect players. A club that tracks other organizations' DSL and complex-league players, not only its own, sees that signal early too."}]}

secs = spec["sections"]
idx = next(i for i, s in enumerate(secs) if s.get("kicker") == "Clubs")
spec["sections"] = secs[:idx] + [types, size, path] + secs[idx:]
spec["method"]["items"].insert(4, {"b": "Part 2 (player types, sizes, early paths):", "t": "PREREG_v2.md was sealed before any split by position, size, age or path. Position at signing comes from the signing transaction text. Size comes from the earliest public list within two seasons of signing. Pro-season levels come from assignments mapped to team levels. 'Full-season' means Low-A or higher. Q1 (position) and Q2 (size, four sub-tests) fail; Q3 (year-three path vs bonus) passes; Q4 (age, rerun on listed players after a cohort flaw, see PREREG_v2_AMENDMENTS.md) fails. Benjamini–Hochberg at 0.10 across the eight: only Q3 survives."})
json.dump(spec, open(OUT / "spec_v2.json", "w"), indent=1, ensure_ascii=False)
print("ok", len(spec["sections"]))
